func drawGutter(canvasW: CGFloat, canvasH: CGFloat) {
    NSColor(white: 0.55, alpha: 0.22).setStroke()
    let gline = NSBezierPath()
    gline.move(to: NSPoint(x: canvasW/2, y: M * 0.4))
    gline.line(to: NSPoint(x: canvasW/2, y: canvasH - M * 0.4))
    gline.lineWidth = 1
    gline.stroke()
}

func drawLabel(book: String, no: Int, ids: [String], canvasW: CGFloat, canvasH: CGFloat) {
    let title = "\(book)-\(String(format: "%02d", no))"
