        .font: NSFont.monospacedSystemFont(ofSize: 11, weight: .medium),
        .foregroundColor: NSColor(calibratedWhite: 0.42, alpha: 1)
    ]
    (title as NSString).draw(at: NSPoint(x: M, y: canvasH - M + 18), withAttributes: attrs)
