}

func render18(_ s: S18) -> NSImage {
    let img = NSImage(size: NSSize(width: SW, height: PH))
    img.lockFocus()
    cream.setFill(); NSRect(x: 0, y: 0, width: SW, height: PH).fill()
    let C = content18()
    switch s.kind {
    case .heroV(let a):
        // 竖图跨页：压书脊，左右外缘留白；识脸避开中缝
        let (cg, pw, ph) = loadCG(a)!
        let (sx, sy) = subjectCenter(cg: cg)
        let dest = C  // 四周 M 留白，中间仍跨过 SW/2
        let sc = max(dest.width / pw, dest.height / ph)
        let bias = sx < 0.48 ? SW * 0.32 : (sx > 0.52 ? SW * 0.68 : SW * 0.50)
        paint(a, dest: dest, scale: sc, sx: sx, sy: sy, biasX: bias)
        drawGutter(canvasW: SW, canvasH: PH)
    case .twinV(let a, let b):
        // 每页一块，外框留白 + 中缝缝隙
        let pageInnerW = (C.width - G) / 2
        drawV(a, in: NSRect(x: C.minX, y: C.minY, width: pageInnerW, height: C.height))
        drawV(b, in: NSRect(x: C.minX + pageInnerW + G, y: C.minY, width: pageInnerW, height: C.height))
    case .threeV(let a, let b, let c):
        let w = (C.width - 2*G) / 3
        drawV(a, in: NSRect(x: C.minX, y: C.minY, width: w, height: C.height))
        drawV(b, in: NSRect(x: C.minX + w + G, y: C.minY, width: w, height: C.height))
        drawV(c, in: NSRect(x: C.minX + 2*(w + G), y: C.minY, width: w, height: C.height))
    case .bandH(let a):
        // 横图真跨页：一张图横跨左右，上下大留白（中腰带）
        let bandH = C.height * bandRatio
        let y = C.midY - bandH / 2
        let (cg, _, _) = loadCG(a)!
        let (sx, _) = subjectCenter(cg: cg)
        drawH(a, in: NSRect(x: C.minX, y: y, width: C.width, height: bandH),
              biasX: sx < 0.5 ? SW * 0.34 : SW * 0.66)
        drawGutter(canvasW: SW, canvasH: PH)
    }
    drawLabel(book: "A", no: s.no, ids: ids18(s.kind), canvasW: SW, canvasH: PH)
    img.unlockFocus(); return img
}

func render12(_ s: S12) -> NSImage {
    let img = NSImage(size: NSSize(width: S, height: P))
