    let img = NSImage(size: NSSize(width: spreadW, height: pageH))
    img.lockFocus()
    cream.setFill(); NSRect(x: 0, y: 0, width: spreadW, height: pageH).fill()
    let C = contentA()
    switch s.kind {
    case .crossH(let a):
        // 竖开本对开上，横图做中腰带真跨页
        let bandH = C.height * bandRatio
        let y = C.midY - bandH / 2
        let (sx, _) = subjectCenter(cg: loadCG(a)!.0)
        drawH(a, in: NSRect(x: C.minX, y: y, width: C.width, height: bandH),
              biasX: sx < 0.5 ? spreadW * 0.34 : spreadW * 0.66)
        drawGutter(w: spreadW, h: pageH)
    case .pageV(let a):
        drawV(a, in: pageRect(left: false, C: C))
    case .pageVLeft(let a):
        drawV(a, in: pageRect(left: true, C: C))
    case .twinV(let a, let b):
        drawV(a, in: pageRect(left: true, C: C))
        drawV(b, in: pageRect(left: false, C: C))
    case .twinH(let a, let b):
        // 每页一张横图：页内上下留白，保持横图比例
        let left = pageRect(left: true, C: C)
        let right = pageRect(left: false, C: C)
        let hBand = left.width / 1.5  // ~3:2
        let yL = left.midY - hBand/2
        let yR = right.midY - hBand/2
        drawH(a, in: NSRect(x: left.minX, y: yL, width: left.width, height: hBand))
        drawH(b, in: NSRect(x: right.minX, y: yR, width: right.width, height: hBand))
    case .oneBigTwoSmall(let a, let b, let c):
        let left = pageRect(left: true, C: C)
        let right = pageRect(left: false, C: C)
        drawV(a, in: left)
        let h = (right.height - G) / 2
        drawV(b, in: NSRect(x: right.minX, y: right.maxY - h, width: right.width, height: h))
        drawV(c, in: NSRect(x: right.minX, y: right.minY, width: right.width, height: h))
    case .threeV(let a, let b, let c):
        let w = (C.width - 2*G) / 3
        drawV(a, in: NSRect(x: C.minX, y: C.minY, width: w, height: C.height))
        drawV(b, in: NSRect(x: C.minX + w + G, y: C.minY, width: w, height: C.height))
        drawV(c, in: NSRect(x: C.minX + 2*(w+G), y: C.minY, width: w, height: C.height))
    }
    drawLabel(book: "A", no: s.no, ids: idsA(s.kind), canvasW: spreadW, canvasH: pageH)
    img.unlockFocus(); return img
}

func renderB(_ s: SB) -> NSImage {
    let img = NSImage(size: NSSize(width: sqSpread, height: sq))
    img.lockFocus()
    cream.setFill(); NSRect(x: 0, y: 0, width: sqSpread, height: sq).fill()
    let C = contentB()
    switch s.kind {
    case .crossH(let a):
        let (sx, _) = subjectCenter(cg: loadCG(a)!.0)
        drawH(a, in: C, biasX: sx < 0.5 ? sqSpread * 0.34 : sqSpread * 0.66)
        drawGutter(w: sqSpread, h: sq)
    case .twinH(let a, let b):
        let w = (C.width - G) / 2
        drawH(a, in: NSRect(x: C.minX, y: C.minY, width: w, height: C.height))
        drawH(b, in: NSRect(x: C.minX + w + G, y: C.minY, width: w, height: C.height))
    case .twinV(let a, let b):
        let w = (C.width - G) / 2
        // 方册里竖图：左右各一，上下可能裁一点
        drawV(a, in: NSRect(x: C.minX, y: C.minY, width: w, height: C.height))
        drawV(b, in: NSRect(x: C.minX + w + G, y: C.minY, width: w, height: C.height))
    case .threeH(let a, let b, let c):
        let w = (C.width - 2*G) / 3
        drawH(a, in: NSRect(x: C.minX, y: C.minY, width: w, height: C.height))
        drawH(b, in: NSRect(x: C.minX + w + G, y: C.minY, width: w, height: C.height))
        drawH(c, in: NSRect(x: C.minX + 2*(w+G), y: C.minY, width: w, height: C.height))
    case .pageV(let a):
        // 右页居中竖图
        let right = NSRect(x: C.midX + G/2, y: C.minY, width: (C.width - G)/2, height: C.height)
        // 竖图在方页里：按高度适配，左右再由槽位裁
        let targetW = right.height * 0.68
        let x = right.midX - targetW/2
        drawV(a, in: NSRect(x: max(x, right.minX), y: right.minY, width: min(targetW, right.width), height: right.height))
    }
    drawLabel(book: "B", no: s.no, ids: idsB(s.kind), canvasW: sqSpread, canvasH: sq)
    img.unlockFocus(); return img
}

