func stack(_ thumbs: [NSImage], tw: CGFloat, th: CGFloat, path: String) {
    let gap: CGFloat = 10
    let ow = tw + 40, oh = 24 + CGFloat(thumbs.count)*(th+gap)
    let o = NSImage(size: NSSize(width: ow, height: oh))
    o.lockFocus(); NSColor(white: 0.12, alpha: 1).setFill(); NSRect(x:0,y:0,width:ow,height:oh).fill()
    for (i,t) in thumbs.enumerated() {
        let y = oh - 12 - CGFloat(i+1)*(th+gap) + gap
        t.draw(in: NSRect(x:20,y:y,width:tw,height:th))
    }
    o.unlockFocus(); saveJPEG(o, to: path, q: 0.82)
}
stack(tA, tw: 640, th: 480, path: OUT_A + "/00-总览.jpg")
stack(tB, tw: 640, th: 320, path: OUT_B + "/00-总览.jpg")

let cellWA: CGFloat = 400, cellHA: CGFloat = 300, cellWB: CGFloat = 440, cellHB: CGFloat = 220
let gapC: CGFloat = 8, pad: CGFloat = 20, header: CGFloat = 64, secT: CGFloat = 34
func secH(_ n: Int, _ h: CGFloat) -> CGFloat { secT + CGFloat((n+1)/2)*(h+gapC) + 6 }
let totalW = pad*2 + 2*max(cellWA, cellWB) + gapC
let totalH = pad + header + secH(tA.count, cellHA) + 12 + secH(tB.count, cellHB) + pad
let canvas = NSImage(size: NSSize(width: totalW, height: totalH))
canvas.lockFocus()
NSColor(calibratedWhite: 0.1, alpha: 1).setFill(); NSRect(x:0,y:0,width:totalW,height:totalH).fill()
func yTop(_ t: CGFloat) -> CGFloat { totalH - t }
var top: CGFloat = pad
("武雅茹 & 闫泽群 · 竖开本 v19" as NSString).draw(at: NSPoint(x: pad, y: yTop(top)-26), withAttributes: [.font: NSFont.systemFont(ofSize: 20, weight: .semibold), .foregroundColor: NSColor.white])
top += 28
("A册：单页宽12×高18（对开24×18）· B册：12×12 · 开本竖≠照片竖 · 留白+真跨页" as NSString).draw(at: NSPoint(x: pad, y: yTop(top)-14), withAttributes: [.font: NSFont.systemFont(ofSize: 12), .foregroundColor: NSColor(white: 0.55, alpha: 1)])
top += header - 28
func drawSec(_ title: String, _ color: NSColor, _ items: [NSImage], _ cw: CGFloat, _ ch: CGFloat) {
    (title as NSString).draw(at: NSPoint(x: pad, y: yTop(top)-20), withAttributes: [.font: NSFont.systemFont(ofSize: 14, weight: .semibold), .foregroundColor: color])
    top += secT
    for (i, im) in items.enumerated() {
        let col = i % 2, row = i / 2
        let x = pad + CGFloat(col)*(cw+gapC)
        let y = yTop(top + CGFloat(row)*(ch+gapC) + ch)
        im.draw(in: NSRect(x: x, y: y, width: cw, height: ch))
    }
    top += CGFloat((items.count+1)/2)*(ch+gapC) + 6
}
drawSec("① A 竖开本 宽12×高18", NSColor(calibratedRed: 1, green: 0.85, blue: 0.55, alpha: 1), tA, cellWA, cellHA)
top += 6
drawSec("② B 方册 12×12", NSColor(calibratedRed: 0.65, green: 0.82, blue: 1, alpha: 1), tB, cellWB, cellHB)
